class Point {
    int x, y;
    Point(int x, int y) { this.x = x; this.y = y; }

    // (a) Passing object to method
    static void printDistance(Point p1, Point p2) {
        double dist = Math.sqrt(
            Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2)
        );
        System.out.printf("Distance: %.2f%n", dist);
    }

    // (b) Returning object from method
    static Point midpoint(Point p1, Point p2) {
        return new Point((p1.x + p2.x) / 2, (p1.y + p2.y) / 2);
    }

    // Pass-by-value demo: changing the reference does NOT affect caller
    static void tryReplace(Point p) {
        p = new Point(99, 99); // only local reference changes
    }

    // But mutating the object DOES affect the caller (same heap object)
    static void mutate(Point p) {
        p.x = 100;
    }

    public static void main(String[] args) {
        Point a = new Point(0, 0);
        Point b = new Point(3, 4);
        printDistance(a, b);        // Distance: 5.00
        Point mid = midpoint(a, b);
        System.out.println("Midpoint: (" + mid.x + "," + mid.y + ")"); // (1,2)
        tryReplace(a);
        System.out.println("After tryReplace: a=" + a.x + "," + a.y); // 0,0
        mutate(a);
        System.out.println("After mutate: a.x=" + a.x); // 100
    }
}

