// Interface with default method
interface Printable {
    void print();  // abstract
    default void info() {
        System.out.println("Printable interface");
    }
}
// Interface inheriting another interface
interface Displayable extends Printable {
    void display();
    default void info() {  // overrides parent default
        System.out.println("Displayable interface");
    }
}
// Second independent interface
interface Serializable {
    void serialize();
}
// Class implementing multiple interfaces
class Report implements Displayable, Serializable {
    @Override
    public void print() {
        System.out.println("Report: Printing...");
    }
    @Override
    public void display() {
        System.out.println("Report: Displaying...");
    }
    @Override
    public void serialize() {
        System.out.println("Report: Serializing...");
    }
}
public class InterfaceDemo {
    public static void main(String[] args) {
        Report r = new Report();
        r.print();
        r.display();
        r.serialize();
        r.info();  // calls Displayable's default info()
        // Interface reference
        Printable p = new Report();
        p.print();
        p.info();  // Displayable's info() via dynamic binding
    }
}
// Output:
// Report: Printing...
// Report: Displaying...
// Report: Serializing...
// Displayable interface
// Report: Printing...
// Displayable interface

