class InsufficientFundsException extends Exception {
    private double shortage;
    InsufficientFundsException(double shortage) {
        super(String.format("Insufficient funds. Short by: %.2f", shortage));
        this.shortage = shortage;
    }
    double getShortage() { return shortage; }
}

// Custom unchecked exception
class InvalidAmountException extends RuntimeException {
    InvalidAmountException(String msg) { super(msg); }
}

class BankAccount {
    private String owner;
    private double balance;

    BankAccount(String owner, double initialBalance) {
        if (initialBalance < 0) throw new InvalidAmountException("Initial balance cannot be negative");
        this.owner = owner;
        this.balance = initialBalance;
    }

    void deposit(double amount) {
        if (amount <= 0) throw new InvalidAmountException("Deposit amount must be positive");
        balance += amount;
        System.out.println("Deposited: " + amount + " | Balance: " + balance);
    }

    void withdraw(double amount) throws InsufficientFundsException {
        if (amount <= 0) throw new InvalidAmountException("Withdrawal amount must be positive");
        if (amount > balance) throw new InsufficientFundsException(amount - balance);
        balance -= amount;
        System.out.println("Withdrawn: " + amount + " | Balance: " + balance);
    }

    double getBalance() { return balance; }
}

public class BankDemo {
    public static void main(String[] args) {
        BankAccount acc = null;
        try {
            acc = new BankAccount("Alice", 1000);
            acc.deposit(500);
            try {
                acc.withdraw(2000); // triggers InsufficientFundsException
            } catch (InsufficientFundsException e) {
                System.out.println("Inner catch: " + e.getMessage());
                System.out.println("Shortage: " + e.getShortage());
            }
            // Multi-catch (Java 7+)
            try {
                acc.deposit(-100); // triggers InvalidAmountException
            } catch (InvalidAmountException | NullPointerException e) {
                System.out.println("Multi-catch: " + e.getMessage());
            }
        } finally {
            System.out.println("Cleanup: Final balance = " + (acc != null ? acc.getBalance() : 0));
        }
    }
}
// Output:
// Deposited: 500.0 | Balance: 1500.0
// Inner catch: Insufficient funds. Short by: 500.00
// Shortage: 500.0
// Multi-catch: Deposit amount must be positive
// Cleanup: Final balance = 1500.0

