import java.util.LinkedList;
import java.util.Queue;

class Buffer {
    private Queue<Integer> queue = new LinkedList<>();
    private final int MAX = 5;

    // Producer
    synchronized void produce(int item) throws InterruptedException {
        while (queue.size() == MAX) {
            System.out.println("Buffer full, producer waiting...");
            wait();  // release lock and wait
        }
        queue.add(item);
        System.out.println("Produced: " + item + " | Buffer size: " + queue.size());
        notifyAll();  // wake all waiting consumers
    }

    // Consumer
    synchronized int consume() throws InterruptedException {
        while (queue.isEmpty()) {
            System.out.println("Buffer empty, consumer waiting...");
            wait();  // release lock and wait
        }
        int item = queue.poll();
        System.out.println("Consumed: " + item + " | Buffer size: " + queue.size());
        notifyAll();  // wake all waiting producers
        return item;
    }
}

class Producer extends Thread {
    Buffer buf;
    Producer(Buffer b) { buf = b; }
    public void run() {
        try {
            for (int i = 1; i <= 8; i++) {
                buf.produce(i);
                Thread.sleep(100);
            }
        } catch (InterruptedException e) { e.printStackTrace(); }
    }
}

class Consumer extends Thread {
    Buffer buf;
    Consumer(Buffer b) { buf = b; }
    public void run() {
        try {
            for (int i = 1; i <= 8; i++) {
                buf.consume();
                Thread.sleep(200);
            }
        } catch (InterruptedException e) { e.printStackTrace(); }
    }
}

public class ProducerConsumer {
    public static void main(String[] args) {
        Buffer buffer = new Buffer();
        Producer p = new Producer(buffer);
        Consumer c = new Consumer(buffer);
        p.start();
        c.start();
    }
}

// DEADLOCK DEMO
public class DeadlockDemo {
    static Object lock1 = new Object();
    static Object lock2 = new Object();

    static Thread threadA = new Thread(() -> {
        synchronized (lock1) {
            System.out.println("Thread A: holds lock1, waiting for lock2");
            try { Thread.sleep(100); } catch (Exception e) {}
            synchronized (lock2) {  // waits here — Thread B holds lock2
                System.out.println("Thread A: holds both locks");
            }
        }
    });

    static Thread threadB = new Thread(() -> {
        synchronized (lock2) {
            System.out.println("Thread B: holds lock2, waiting for lock1");
            try { Thread.sleep(100); } catch (Exception e) {}
            synchronized (lock1) {  // waits here — Thread A holds lock1
                System.out.println("Thread B: holds both locks");
            }
        }
    });

    public static void main(String[] args) {
        threadA.start();
        threadB.start();
        // Program hangs — deadlock!
    }
}

// DEADLOCK FIX: always acquire locks in the same order
public class DeadlockFixed {
    static Object lock1 = new Object();
    static Object lock2 = new Object();

    static Thread threadA = new Thread(() -> {
        synchronized (lock1) {           // BOTH threads acquire lock1 first
            synchronized (lock2) {
                System.out.println("A: has both locks");
            }
        }
    });

    static Thread threadB = new Thread(() -> {
        synchronized (lock1) {           // same order: lock1 then lock2
            synchronized (lock2) {
                System.out.println("B: has both locks");
            }
        }
    });

    public static void main(String[] args) {
        threadA.start();
        threadB.start();
    }
}

public class ThreadLifecycle {

    public static void main(String[] args) throws InterruptedException {
        // 1. Creating thread (NEW state)
        Thread worker = new Thread(() -> {
            System.out.println("Worker: running (state=RUNNABLE/RUNNING)");
            try {
                Thread.sleep(2000);  // TIMED_WAITING
                System.out.println("Worker: woke up after sleep");
            } catch (InterruptedException e) {
                System.out.println("Worker: interrupted!");
            }
        }, "WorkerThread");

        // Setting priority
        worker.setPriority(Thread.MAX_PRIORITY);  // 10
        System.out.println("Priority: " + worker.getPriority());  // 10
        System.out.println("State before start: " + worker.getState()); // NEW

        worker.start();
        System.out.println("State after start: " + worker.getState()); // RUNNABLE or TIMED_WAITING

        // Daemon thread: JVM exits when only daemon threads remain
        Thread daemon = new Thread(() -> {
            while (true) {
                System.out.println("Daemon running...");
                try { Thread.sleep(500); } catch (Exception e) { break; }
            }
        });
        daemon.setDaemon(true);  // must set before start()
        daemon.start();

        // join: main waits for worker to finish
        worker.join();
        System.out.println("State after join: " + worker.getState()); // TERMINATED
        System.out.println("Main thread done");
        // JVM exits, daemon thread stops automatically
    }
}

