import java.applet.Applet;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;

public class LifecycleApplet extends Applet implements Runnable {
    // Parameters
    String title;
    Color bgColor;

    // Animation state
    int ballX = 50, ballY = 100;
    int dx = 5, dy = 3;
    Thread animThread;
    boolean running = false;

    // (a) Lifecycle methods
    public void init() {
        System.out.println("init() called - once");
        title = getParameter("title");
        if (title == null) title = "OOP Demo";
        String col = getParameter("bgcolor");
        bgColor = "red".equals(col) ? Color.RED : Color.CYAN;
        setBackground(bgColor);
    }

    public void start() {
        System.out.println("start() called");
        running = true;
        animThread = new Thread(this);
        animThread.start();
    }

    public void stop() {
        System.out.println("stop() called");
        running = false;
    }

    public void destroy() {
        System.out.println("destroy() called - once");
    }

    // (c) Drawing
    public void paint(Graphics g) {
        g.setFont(new Font("Arial", Font.BOLD, 16));
        g.setColor(Color.DARK_GRAY);
        g.drawString(title, 10, 20);

        // (d) Bouncing ball animation
        g.setColor(Color.RED);
        g.fillOval(ballX, ballY, 30, 30);
    }

    // (d) Animation thread
    public void run() {
        while (running) {
            ballX += dx;
            ballY += dy;
            if (ballX < 0 || ballX > 370) dx = -dx;  // bounce X
            if (ballY < 0 || ballY > 220) dy = -dy;  // bounce Y
            repaint();
            try { Thread.sleep(50); } catch (InterruptedException e) { break; }
        }
    }
}

