public class CalcApplet extends Applet {
    double num1, num2;
    String error = null;

    public void init() {
        try {
            String n1 = getParameter("num1");
            String n2 = getParameter("num2");
            num1 = (n1 != null) ? Double.parseDouble(n1) : 0;
            num2 = (n2 != null) ? Double.parseDouble(n2) : 0;
        } catch (NumberFormatException e) {
            error = "Invalid parameters: " + e.getMessage();
        }
    }

    public void paint(Graphics g) {
        g.setFont(new Font("Monospaced", Font.PLAIN, 14));
        int y = 30;
        if (error != null) {
            g.setColor(Color.RED);
            g.drawString(error, 10, y);
            return;
        }
        g.setColor(Color.BLACK);
        g.drawString("num1 = " + num1 + "   num2 = " + num2, 10, y); y += 25;
        g.setColor(Color.BLUE);
        g.drawString("Addition:       " + (num1 + num2), 10, y); y += 20;
        g.drawString("Subtraction:    " + (num1 - num2), 10, y); y += 20;
        g.drawString("Multiplication: " + (num1 * num2), 10, y); y += 20;
        if (num2 != 0)
            g.drawString("Division:       " + (num1 / num2), 10, y);
        else {
            g.setColor(Color.RED);
            g.drawString("Division: Cannot divide by zero!", 10, y);
        }
    }
}

